package vn.hoangminh.erp.Ht3DieuPhoi.repository; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; import jakarta.persistence.LockModeType; import vn.hoangminh.erp.Ht3DieuPhoi.domain.ChuyenVan; import java.util.*; public interface ChuyenVanRepository extends JpaRepository<ChuyenVan,Integer> { @Lock(LockModeType.PESSIMISTIC_WRITE) @Query("select c from ChuyenVan c where c.maChuyen=:id") Optional<ChuyenVan> khoa(@Param("id") Integer id); List<ChuyenVan> findByMaTaiXe(String maTaiXe); }
